package net.officefloor.hq.app.audit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import org.springframework.stereotype.Service;

/**
 * Reads the audit file back for the viewer: it is not a second record, only what the file holds.
 */
@Service
public class AuditViewService {

    /** The start of a field: a space, then its key and '='. A field's value runs to the next field. */
    private static final Pattern FIELD = Pattern.compile(" ([a-z][a-z0-9-]*)=");

    private final Audit audit;

    public AuditViewService(Audit audit) {
        this.audit = audit;
    }

    /**
     * The sheet's lines, newest first. With a non-blank name, only the lines whose name= or person=
     * field is that name, compared as names are (case and surrounding spaces ignored).
     */
    public List<String> lines(String sheetId, String name) {
        String wanted = name == null ? "" : normal(name);
        List<String> found = new ArrayList<>();
        for (String line : audit.lines()) {
            if (!field(line, "sheet").filter(sheetId::equals).isPresent()) {
                continue;
            }
            if (!wanted.isEmpty() && !about(line, wanted)) {
                continue;
            }
            found.add(line);
        }
        Collections.reverse(found);
        return found;
    }

    private static boolean about(String line, String wanted) {
        return field(line, "name").map(AuditViewService::normal).filter(wanted::equals).isPresent()
                || field(line, "person").map(AuditViewService::normal).filter(wanted::equals).isPresent();
    }

    /** The value of the line's first field with this key, up to the next field. */
    private static Optional<String> field(String line, String key) {
        Matcher m = FIELD.matcher(line);
        while (m.find()) {
            if (!m.group(1).equals(key)) {
                continue;
            }
            int start = m.end();
            int end = m.find() ? m.start() : line.length();
            return Optional.of(line.substring(start, end));
        }
        return Optional.empty();
    }

    private static String normal(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

// The audit viewer: the active sheet's audit lines exactly as the file holds them, newest first;
// with a name in the filter, only the lines about that person.
@Component({
  selector: 'app-audit-viewer',
  template: `
    <section aria-labelledby="audit-heading">
      <h2 id="audit-heading">Audit</h2>
      <form (submit)="show($event)">
        <label for="audit-filter">Person</label>
        <input
          id="audit-filter"
          data-testid="audit-filter"
          [value]="filter()"
          (input)="filter.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="audit-show">Show audit</button>
        @if (error(); as message) {
          <p role="alert" data-testid="audit-error">{{ message }}</p>
        }
      </form>
      <ol>
        @for (line of lines(); track $index) {
          <li data-testid="audit-line">{{ line }}</li>
        }
      </ol>
    </section>
  `,
})
export class AuditViewer {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);
  protected readonly filter = signal('');
  protected readonly lines = signal<string[]>([]);
  protected readonly error = signal<string | null>(null);
  /** Counts presses, so only the latest press's answer is shown. */
  private shows = 0;

  constructor() {
    // A sheet (re-)load clears what an earlier press showed.
    effect(() => {
      this.session.sheetId();
      this.session.loads();
      this.shows++;
      this.lines.set([]);
    });
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  /** Read the sheet's audit lines, filtered to the typed name when one is typed. */
  protected async show(event: Event): Promise<void> {
    event.preventDefault();
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const press = ++this.shows;
    this.error.set(null);
    this.lines.set([]);
    const name = this.filter().trim();
    try {
      const lines = await firstValueFrom(
        this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/audit`, {
          params: name ? { name } : {},
        }),
      );
      if (press === this.shows) this.lines.set(lines);
    } catch {
      if (press === this.shows) this.error.set('The audit could not be read.');
    }
  }
}

